// Package v1 has a field that shadows a promoted field, for which the
// With<Field> function generated by applyconfiguration-gen sets the promoted
// field: https://github.com/kubernetes/kubernetes/issues/143416
// +groupName=testdata.kubebuilder.io
// +versionName=v1
// +kubebuilder:ac:generate=true
package v1

import (
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// +kubebuilder:object:root=true
// +kubebuilder:resource

type Widget struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec WidgetSpec `json:"spec,omitempty"`
}

type WidgetSpec struct {
	Override   Override   `json:"override,omitempty"`
	FieldFirst FieldFirst `json:"fieldFirst,omitempty"`
}

type Base struct {
	Enabled bool   `json:"enabled,omitempty"`
	Mode    string `json:"mode,omitempty"`
}

// Override declares Enabled after the embedded Base, so it must be reported.
type Override struct {
	Base `json:",inline"`

	Enabled *bool `json:"enabled,omitempty"`
}

// FieldFirst declares Enabled before the embedded Base, which generates a
// working WithEnabled, so it must not be reported.
type FieldFirst struct {
	Enabled *bool `json:"enabled,omitempty"`

	Base `json:",inline"`
}
